import { 
  MeshBasicNodeMaterial, 
  PlaneGeometry, 
  Mesh, 
  Group 
} from 'three/webgpu';
import { gsap } from 'gsap';
import { createText } from '@/text';

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];

  // Build the sprite plane
  const aspect = 512 / 320; // from atlas source rect
  const geometry = new THREE.PlaneGeometry(1.6, 1); // width = 1.6, height = 1
  const material = new MeshBasicNodeMaterial({
    transparent: true,
    map: null,
    depthWrite: false,
  });
  const plane = new Mesh(geometry, material);

  // Load texture and apply to material
  const texturePromise = ctx.textureLoader.loadTexture(config.imageUrl);
  texturePromise.then((tex) => {
    tex.wrapS = tex.wrapT = THREE.ClampToEdgeWrapping;
    // No UV offset – assume the image is exactly the sprite region
    material.map = tex;
    material.needsUpdate = true;
  }).catch(() => {}); // ignore failure, will show plain black

  // Create text content
  const textGroup = new Group();
  if (items.length > 0) {
    const textItem = items[0];
    const fontSize = textItem.typography?.fontSize 
      ? parseFloat(textItem.typography.fontSize) 
      : 0.34; // headline scene units per design token
    const textMesh = ctx.fontAtlas.createText(textItem.text, {
      fontSize: fontSize,
      color: '#e8ecf2', // paper color
      align: 'center',
      letterSpacingPx: 0.02 * fontSize,
    });
    // Center on plane
    textMesh.position.set(0, 0, 0.01); // slightly in front
    textGroup.add(textMesh);
  }

  // Compose
  const group = new Group();
  group.add(plane);
  group.add(textGroup);

  // Static composition – no animations, no primitives, no interactivity
  // (config.cinematicPrimitives is empty)

  // Cleanup
  group.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    if (material.map) material.map.dispose();
    // Kill any GSAP timelines (none in this node)
    gsap.killTweensOf(group);
    // Dispose text meshes if needed (fontAtlas manages cache)
    textGroup.traverse((child) => {
      if (child.isMesh) {
        child.geometry.dispose();
        if (child.material) child.material.dispose();
      }
    });
  };

  // For static sprite, no event handlers
  group.userData.handlers = {};

  return group;
}
